TLM.f("Tempora/Quad5-4",{"officium":"Feria Quinta infra Hebdomadam Passionis","rule":["no Gloria","Suffragium=Ecclesiæ,Papa;;","Prefatio=Quad5","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"fallback":"Tempora/Quad5-0","sections":{"Introitus":[{"k":"ref","la":"Dan 3:31"},{"k":"text","la":"Omnia, quæ fecísti nobis, Dómine, in vero judício fecísti: quia peccávimus tibi, et mandátis tuis non obedívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"text","la":"Omnia, quæ fecísti nobis, Dómine, in vero judício fecísti: quia peccávimus tibi, et mandátis tuis non obedívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut dígnitas condiciónis humánæ, per immoderántiam sauciáta, medicinális parsimóniæ stúdio reformétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Daniélis Prophétæ"},{"k":"ref","la":"Dan 3:25, 34-45"},{"k":"text","la":"In diébus illis: Orávit Azarías Dóminum, dicens: Dómine, Deus noster: ne, quǽsumus, tradas nos in perpétuum propter nomen tuum, et ne díssipes testaméntum tuum: neque áuferas misericórdiam tuam a nobis propter Abraham diléctum tuum, et Isaac servum tuum, et Israël sanctum tuum: quibus locútus es, póllicens, quod multiplicáres semen eórum sicut stellas cœli, et sicut arénam, quæ est in líttore maris: quia, Dómine, imminúti sumus plus quam omnes gentes, sumúsque húmiles in univérsa terra hódie propter peccáta nostra. Et non est in témpore hoc princeps, et dux, et prophéta, neque holocáustum, neque sacrifícium, neque oblátio, neque incénsum, neque locus primitiárum coram te, ut possímus inveníre misericórdiam tuam: sed in ánimo contríto et spíritu humilitátis suscipiámur. Sicut in holocáusto aríetum et taurórum, et sicut in míllibus agnórum pínguium: sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi: quóniam non est confúsio confidéntibus in te. Et nunc séquimur te in toto corde, et timémus te, et quǽrimus fáciem tuam. Ne confúndas nos: sed fac nobíscum juxta mansuetúdinem tuam et secúndum multitúdinem misericórdiæ tuæ. Et érue nos in mirabílibus tuis, et da glóriam nómini tuo, Dómine: et confundántur omnes, qui osténdunt servis tuis mala, confundántur in omni poténtia tua: et robur eórum conterátur: et sciant, quia tu es Dóminus, Deus solus, et gloriósus super orbem terrárum, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 95:8-9"},{"k":"text","la":"Tóllite hóstias, et introíte in átria ejus: adoráte Dóminum in aula sancta ejus"},{"k":"ref","la":"Ps 28:9"},{"k":"text","la":"Revelávit Dóminus condénsa: et in templo ejus omnes dicent glóriam."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 7:36-50"},{"k":"text","la":"In illo témpore: Rogábat Jesum quidam de pharisǽis, ut manducáret cum illo. Et ingréssus domum pharisǽi, discúbuit. Et ecce múlier, quæ erat in civitáte peccátrix, ut cognóvit, quod accubuísset in domo pharisǽi, áttulit alabástrum unguénti: et stans retro secus pedes ejus, lácrimis cœpit rigáre pedes ejus, et capíllis cápitis sui tergébat, et osculabátur pedes ejus, et unguénto ungébat. Videns autem pharisǽus, qui vocáverat eum, ait intra se, dicens: Hic si esset Prophéta, sciret útique, quæ et qualis est múlier, quæ tangit eum: quia peccátrix est. Et respóndens Jesus, dixit ad illum: Simon, hábeo tibi áliquid dícere. At ille ait: Magíster, dic. Duo debitóres erant cuidam fœneratóri: unus debébat denários quingéntos, et álius quinquagínta. Non habéntibus illis, unde rédderent, donávit utrísque. Quis ergo eum plus díligit? Respóndens Simon, dixit: Æstimo, quia is, cui plus donávit. At ille dixit ei: Recte judicásti. Et convérsus ad mulíerem, dixit Simóni: Vides hanc mulíerem? Intrávi in domum tuam, aquam pédibus meis non dedísti: hæc autem lácrimis rigávit pedes meos et capíllis suis tersit. Osculum mihi non dedísti: hæc autem, ex quo intrávit, non cessávit osculári pedes meos. Oleo caput meum non unxísti: hæc autem unguénto unxit pedes meos. Propter quod dico tibi:Remittúntur ei peccáta multa, quóniam diléxit multum. Cui autem minus dimíttitur, minus díligit. Dixit autem ad illam: Remittúntur tibi peccáta. Et cœpérunt, qui simul accumbébant, dícere intra se: Quis est hic, qui étiam peccáta dimíttit? Dixit autem ad mulíerem: Fides tua te salvam fecit: vade in pace."}],"Offertorium":[{"k":"ref","la":"Ps 136:1"},{"k":"text","la":"Super flúmina Babylónis illic sédimus et flévimus: dum recordarémur tui, Sion."}],"Secreta":[{"k":"text","la":"Dómine, Deus noster, qui in his pótius creatúris, quas ad fragilitátis nostræ subsídium condidísti, tuo quoque nómini múnera jussísti dicánda constítui: tríbue, quǽsumus; ut et vitæ nobis præséntis auxílium et æternitátis effíciant sacraméntum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:49-50"},{"k":"text","la":"Meménto verbi tui servo tuo, Dómine, in quo mihi spem dedísti: hæc me consoláta est in humilitáte mea."}],"Postcommunio":[{"k":"text","la":"Quod ore súmpsimus, Dómine, pura mente capiámus: et de munere temporáli, fiat nobis remédium sempitérnum."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Esto, quǽsumus, Dómine, propítius plebi tuæ: ut, quæ tibi non placent, respuéntes; tuórum pótius repleántur delectatiónibus mandatórum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"0f20c771e95c39e3":{"t":"Dn 3, 31 i 29 i 35, Ps 118, 1\n(Dn 3, 31 i 29 i 35) Imao si pravo, Gospodine, sa svim što si nam učinio, jer smo sagriješili tebi i tvojim se zapovijedima nismo pokoravali. Ali proslavi ime svoje i učini s nama po mnoštvu smilovanja svoga. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dn 3, 31 i 29 i 35) Imao si pravo, Gospodine, sa svim što si nam učinio, jer smo sagriješili tebi i tvojim se zapovijedima nismo pokoravali. Ali proslavi ime svoje i učini s nama po mnoštvu smilovanja svoga.","kn":"(Dan. 3. 21-35). Sve, što si učinio nama, Gospodine, u pravom si sudu učinio, jer sagriješismo proti Tebi i ne .poslušasmo zapovijedi Tvojih; ali daj slavu imenu svojemu, 1 učini s nama po mnoštvu milosrđa svojega. (Ps. 118, 1) Blago onima, koji su čista života, koji žive po zakonu Gospodnjem.","knRef":"Kniewald 1942, str. 422–423 (snimka 212) (OCR)"},"8be62f5978b01343":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da se dostojanstvo ljudske naravi ranjene neumjerenošću obnovi revnošću u spasonosnom uzdržavanju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da se dostojanstvo ljudske prirode, ozlijeđeno neumjerenošču, preporodi nastojanjem ljekovitog uzdržavanja, po G. n.","knRef":"Kniewald 1942, str. 206–207 (snimka 104) (OCR)"},"5f4df3d6a5eb7622":{"t":"Dn 3, 25 i 34-45\nČitanje Danijela proroka. U one dane pomoli se Azarija Gospodinu i reče: Gospodine Bože naš, ne odbaci nas zauvijek radi svojeg imena, ne kidaj svojega zavjeta! Ne uskrati nam svojega milosrđa radi svoga ljubimca Abrahama i svoga sluge Izaka i svoga svetog Izraela, kojima si obećao da ćeš njihovo potomstvo umnožiti kao zvijezde na nebu i kao pijesak, na obali morskoj. Gospodine, mi smo manji od sviju naroda i poniženi zbog svojih grijeha po svoj zemlji. I u ovo doba nemamo ni kneza, ni vođe, ni proroka, ni žrtava paljenica, ni klanica, ni prinosa, ni kada, ali ni mjesta da ti prinosimo prvine, da zadobijemo tvoje milosrđe. Primi nas skrušene u srcu i ponizne u duhu! Kao žrtva ovnova i junaca tisuće pretilih janjaca neka ti danas bude mila naša žrtva pred tobom, jer se neće postidjeti oni, koji se uzdaju u tebe. Štujemo te svim srcem, bojimo se tebe i tražimo te. Ne daj da se zastidimo, nego nam udijeli po svojoj milosti i mnoštvu tvojega milosrđa. Svojim nas čudesima oslobodi, proslavi, Gospodine, svoje ime, da se postide svi koji čine zlo tvojim slugama, da se postide pred tvojom svemogućnošću i da se slomi njihova snaga, te spoznaju da si ti sam Bog, Gospodar i slavan na cijeloj zemlji, Gospodine Bože naš.","kn":"Čitanje Daniela Proroka (3, 25 i 34-45). U one dane: Azarija se pomoli Gospodinu govoreći: Gospodine, Bože naš, ne zapusti nas, molimo, na vijeke, radi Imena svojega, i ne razriješi zavjet svoj, niti nam uskrati milosrđe svoje radi Abrahama ljubljenoga svoga, i Izaka sluge svojega, i Izraela .svetoga svoga, kojima si govorio obećavajući, da ćeš umnožiti potomstvo njihovo kao zvijezde na nebu, i kao pijesak, što se nalazi na obali morskoj, jer smo se, Gospodine, umanjili više od svih naroda, i poniženi smo danas po svoj zemlji radi grijeha svojih. I nema u ovo doba kneza, ni vođe, ni proroka, ni žrtava paljenica, ni posvetilišta, ni pri nosa, ni tamjana, ni mjesta, gdje bismo ti prinosili prvine, da zadobijemo milosrđe tvoje: nego nae primi skrušene srcem 1 ponižene duhom. Kao žrtva ovnova i junaca, i kao tisuća pretilih janjčića: tako da bude danas posvetilište naše pred licem tvojim, da ti se dopadne; jer oni, koji se u te uzdaju, ne će se zastidjeti. Eto te štujemo svim srcem, i bojimo se tebe, i tražimo lice tvoje. Ne daj, da se zastidimo; nego učini s nama po dobroti svojoj, i po velikom milosrđu svome. I izbavi nas po svojim čudesima, i proslavi Ime svoje, Gospodine; da se zastide svi oni, koji čine zlo slugama tvojim, da se zastide od tvojega svemogućstva, i da se skrši sila njihova: te upoznadu, da si ti Gospodin Bog sam, i slavan po svoj vasioni. Gospodine, Bože naš.","knRef":"Kniewald 1942, str. 206–207 (snimka 104) (OCR)"},"9ac2ac9c8d357a8d":{"t":"Ps 95, 8-9, Ps 28, 9\n(Ps 95, 8-9) Prinesite žrtve i uđite u dvore njegove. Klanjajte se Gospodinu u svetom hramu njegovu. (Ps 28, 9) Gospodin razvaljuje guštaru, a u hramu njegovu svi govore: Slava.","kn":"(Ps. 95, 8, 9). Prinosite žrtve 1 stupajte u dvore njegove, klanjajte se Gospodinu u hramu njegovu! (Ps. 28, 9). Razgaljuje Gospodin guštaru 1 u hramu njegovu svi govore: Slava!","knRef":"Kniewald 1942, str. 206–207 (snimka 104) (OCR)"},"e5f50f95a3c0903d":{"t":"Lk 7, 36-50\nSlijedi sveto Evanđelje po Luki. U ono vrijeme neki farizej pozove Isusa na gozbu. Uđe u farizejevu kuću, sjedne za stol, a neka grješnica, kada je doznala da je za stolom u farizejevoj kući, dođe, donese sobom alabastrovu posudu pomasti, stane iza njega do njegovih nogu, poče plakati, suzama mu prati noge, otirati ih svojom kosom, ljubiti ih i mazati ih pomašću. Kada to vidi farizej koji ga je pozvao, pomisli: Da je ovaj prorok, znao bi tko i kakva je žena koja ga se dotiče: da je grješnica. Isus mu reče: Šimune, imam ti nešto kazati. On odgovori: Kaži, Učitelju! Isus reče: Imao je vjerovnik dva dužnika. Jedan je dugovao petsto dinara, a drugi pedeset. On oprosti obojici, jer nisu mogli vratiti. Koji će ga od one dvojice više ljubiti? Šimun odgovori: Mislim onaj kojemu je više oprostio. Isus mu reče: Ispravno si sudio. Pokazujući na ženu upita Šimuna: Vidiš li ovu ženu? Ušao sam u tvoju kuću, nisi mi polio noge vodom, a ona mi je suzama oprala noge i otrla ih svojom kosom. Nisi mi dao poljupca, a ona otkad uđe, ne prestaje cjelivati mojih nogu; nisi mi glave namazao uljem, a ona mi je noge pomazala miomirisnom pomasti. Zato ti kažem: Njoj se opraštaju mnogi grijesi, jer je ljubila mnogo. Kome se manje oprašta, ljubi manje. A ženi reče: Oprošteni su ti grijesi! I oni, koji su sjedili za stolom s njim, pitali su se u sebi: Tko je ovaj da oprašta grijehe? Tada reče ženi: Spasila te tvoja vjera. Idi u miru!","kn":"t Slijedi sv. evanđelje po Luki (7, 36-50). U ono je vrijeme molio Isusa jedan od farizeja, da bi jeo s njim. I ušavši u kuću farizejsku, sjede za stol. I gle, žena, koja je bila griješnica u gradu, doznavši, da je on za stolom u kući farizejevoj, donese posudicu od alabastra s pomasti. I stavi straga kod nogu njegovih, plačući stade suzama prati noge njegove i kosom s glave svoje otare ih, te je cjelivala noge njegove i pomasti mazala. Kad to vidje farizej, koji ga je pozvao, pomisli u sebi: Da je ovo prorok, znao bi dakako, tko i kakva je žena, koja ga se dotiče, da je grješnica. Tada prozbori Isus i reče mu: Simune, imam ti nešto kazati. On reče; Učitelju, kaži! Dvojica su bili dužni jednome vje- rovniku; jedan je bio dužan pet stotina dinara, a drugi pedeset. A kad oni ne imadoše, odakle da vrate, pokloni obojici. Koji će ga dakle od njih više ljubiti? Odgovori Simun: Mislim, da onaj, komn je više poklonio. On mu reče: Pravo si sudio. I okrenuvši se k ženi, reče Simunu: Vidiš li ovu ženu?Uđoh u tvoju kuću, vode mi na noge nisi dao, a ova suzama obli moje noge i svojom kosom otare. C jelova mi nisi dao; a ova, otkako uđe, ne presta cjelivati nogu mojih. Uljem nisi pomazao glave moje, a ona pomašću pomaza noge moje. Zato ti kažem; Oprošteni su joj mnogi grijesi; jer je mnogo ljubila; a kome se manje prašta, manje ljubi. A njoj reče; Oprošteni su ti grijesi. I stadoše misliti u sebi oni, što su sjedili s njime za stolom: Tko je ovaj, da i grijehe oprašta? A ženi reče: Vjera ti je tvoja pomogla, idi u miru!","knRef":"Kniewald 1942, str. 206–207 (snimka 104) (OCR)"},"5516328e767399ed":{"t":"Ps 136, 1\nNa babilonskim rijekama sjedili smo i plakali sjećajući se tebe, Sione.","kn":"(Ps. 136, 1). Sjedili smo nad rijekama Babilona i plakali srao sjećajući se Tebe, Sionel","knRef":"Kniewald 1942, str. 208–209 (snimka 105) (OCR)"},"748c928565cefb84":{"t":"Gospodine, Bože naš, koji si naredio da se upravo od onih stvorenja, koja si ustanovio za hranu našoj krhkoj naravi, uzmu darovi koje ćemo tvome imenu prikazati, podaj, molimo, da nam oni budu pomoć u sadašnjem životu i sredstvo posvećenja za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu_ je dostojno i pravedno, pravo i. spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, po Kristu, 1 Gospodinu: našemu: jer Ti si ustanovio spase- I nje ljudskog roda na drvetu križa, da odanle us krsne život, odakle je proizašla smrt, te onaj, koji je na drvetu iznio pobjedu, na drvetu bude i svla- J dan po Kristu, Gospodinu našem, po kojem veličan stvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te i nebeske moći i blaženi Serafini zajedno slave, Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"1cbe7ebd0816089b":{"t":"Ps 118, 49-50\nSpomeni se svoje riječi slugi svojemu, Gospodine, po kojoj mi ulijevaš pouzdanje. U mojoj me nevolji utješi.","kn":"(Po 118, 49). Opomeni se riječi Tvoje, sluzi tvojemu. Gospodine, kojom mi nadu dade; ona me je, utješila u smjernosti mojoj.","knRef":"Kniewald 1942, str. 424–425 (snimka 213) (OCR)"},"cd4a13f50dd44203":{"t":"<i>Pomolimo se</i>.\nGospodine, daj da čistom dušom prihvatimo što smo primili ustima, da nam ovaj vremeniti dar postane okrepom za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo. Gospodine, da čistim srcem obuhvatimo, što ustima primismo, 1 da nam vremeniti dar bude za vječnu okrepu, po G. n.","knRef":"Kniewald 1942, str. 208–209 (snimka 105) (OCR)"},"10166262eecfca65":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nMilostiv budi svome narodu, molimo, Gospodine, da odbaci što se tebi ne sviđa i da što više osjeti milinu tvojih zapovijedi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
